/* From Uiverse.io by Tsiangana  - Tags: animation, loader, loading animation, anime */
.__UIV_SCOPE__ .loader {
  width: 200px;
  height: 200px;
  display: flex;
  align-items: center;
  justify-content: center;
  animation: float 2s ease-in-out infinite;
}

@keyframes float {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-12px);
  }
}

.__UIV_SCOPE__ .loader:before {
  content: "";
  width: 10px;
  height: 7px;
  border-radius: 50%;
  background-color: rgba(0, 0, 0, 0.9);
  position: absolute;
  bottom: -9px;
  animation: shadow046 2s alternate infinite ease;
}
@keyframes shadow046 {
  0% {
    transform: scaleX(1);
  }
  40% {
    transform: scaleX(15);
    opacity: 0.7;
  }
}

.__UIV_SCOPE__ .circle {
  width: 140px;
  height: 140px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  position: absolute;
}
.__UIV_SCOPE__ .loader .p1 {
  height: 20px;
  width: 7px;
  background-color: #ffe71c;
  position: absolute;
  margin-top: -118px;
  margin-left: 3px;
}
.__UIV_SCOPE__ .loader .p2 {
  height: 20px;
  width: 7px;
  background-color: #ffe71c;
  position: absolute;
  margin-top: 118px;
  margin-left: 3px;
}

.__UIV_SCOPE__ .loader .p3 {
  height: 20px;
  width: 7px;
  background-color: #ffe71c;
  position: absolute;
  transform: rotate(90deg);
  margin-right: -120px;
}
.__UIV_SCOPE__ .loader .p4 {
  height: 20px;
  width: 7px;
  background-color: #ffe71c;
  position: absolute;
  transform: rotate(90deg);
  margin-right: 119px;
}
.__UIV_SCOPE__ .loader .p5 {
  height: 25px;
  width: 7px;
  background-color: #ffe71c;
  position: absolute;
  margin-top: -84px;
  margin-right: -89px;
  transform: rotate(45deg);
}
.__UIV_SCOPE__ .loader .p6 {
  height: 23px;
  width: 7px;
  background-color: #ffe71c;
  position: absolute;
  margin-top: 88px;
  margin-right: 84px;
  transform: rotate(45deg);
}
.__UIV_SCOPE__ .loader .p7 {
  height: 23px;
  width: 7px;
  background-color: #ffe71c;
  position: absolute;
  margin-top: -86px;
  margin-right: 80px;
  transform: rotate(-45deg);
}
.__UIV_SCOPE__ .loader .p8 {
  height: 23px;
  width: 7px;
  background-color: #ffe71c;
  position: absolute;
  margin-top: 80px;
  margin-right: -83px;
  transform: rotate(-45deg);
}
.__UIV_SCOPE__ .circle .traco {
  position: absolute;
  z-index: -99;
}
.__UIV_SCOPE__ .loader .content {
  width: 100px;
  height: 100px;
  border-radius: 50%;
  border: 4px solid #ffe71c;
  overflow: hidden;
}
.__UIV_SCOPE__ .content .eyes {
  width: 80px;
  height: 30px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 18px auto 0px;
  padding: 3.5px 10px;
}
.__UIV_SCOPE__ .eyes .eye-left {
  width: 22px;
  height: 100%;
  background-color: #ffe71c;
  border-radius: 50%;
}
.__UIV_SCOPE__ .eyes .eye-right {
  width: 22px;
  height: 100%;
  background-color: #ffe71c;
  border-radius: 50%;
}

.__UIV_SCOPE__ .content .nouse {
  margin: -4px auto;
  height: 5px;
  width: 5px;
  border-radius: 50%;
  background-color: #ffe71c;
}
.__UIV_SCOPE__ .content .mouth {
  margin: 9px auto 0;
  height: 3px;
  width: 100%;
  background-color: #ffe71c;
}
.__UIV_SCOPE__ .content .teeth {
  margin: 0 auto;
  height: 37px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 12px;
}
.__UIV_SCOPE__ .teeth .tooth {
  height: 100%;
  width: 4px;
  background-color: #ffe71c;
}
